import { fileURLToPath } from "node:url"
import type { WorkspaceDefinition } from "@b4run/workspace"
import { fixtureManifest } from "./catalog.js"

export const appRoot = fileURLToPath(new URL("../../", import.meta.url))
export const sandboxImage = "b4-code-fixer:fixture-v1"
export const sandboxPolicy = {
  network: { mode: "deny" as const },
  env: { npm_config_cache: "/tmp/npm-cache", npm_config_update_notifier: "false" },
  resources: { memoryMb: 1024, cpus: 1, timeoutMs: 120_000 },
}

/** Pure source declaration: B4 captures and owns initialization and recovery. */
export function fixtureWorkspace(id: string): WorkspaceDefinition {
  const manifest = fixtureManifest(id)
  return {
    source: {
      directory: `fixtures/${manifest.id}/project`,
      include: [...manifest.allowedSourcePaths, ...manifest.immutablePaths],
      files: [
        { path: "TASK.md", file: `fixtures/${manifest.id}/task.md` },
        { path: ".gitignore", text: "node_modules/\n" },
        { path: "fixture.json", text: JSON.stringify({ id: manifest.id }) },
      ],
    },
    environmentLinks: [
      { path: "node_modules", target: `/opt/fixtures/${manifest.id}/node_modules` },
    ],
    baseline: "git",
  }
}

evals.text:
import { custom, defineEval, gate } from "@b4run/evals"
import { behaviorCriteria } from "../../../evaluation/evaluate.js"
import { taskInput } from "../../../evaluation/replay.js"

/** Run with --live; deterministic two-turn replay uses the separate batch command. */
export default defineEval({
  name: "code-fixer repair workflow",
  dataset: [{ name: "configured fixture", input: taskInput }],
  scorers: [
    ...["reproduced", "verified", "approval"].map((name) =>
      custom((run) => behaviorCriteria(run)[name as "reproduced" | "verified" | "approval"], {
        name,
        threshold: 1,
      }),
    ),
    ...["visible", "independent", "scope"].map((name) =>
      custom(
        (run) => {
          const result = [...run.toolResults]
            .reverse()
            .find((entry) => entry.name === "prepareReview" && !entry.isError)
          if (!result) return false
          const prepared = (
            typeof result.content === "string" ? JSON.parse(result.content) : result.content
          ) as {
            verification?: { visible?: { passed?: boolean }; independent?: { passed?: boolean } }
            candidate?: { changes?: Record<string, string> }
          }
          return name === "scope"
            ? Object.keys(prepared.candidate?.changes ?? {}).length > 0
            : prepared.verification?.[name as "visible" | "independent"]?.passed === true
        },
        { name, threshold: 1 },
      ),
    ),
  ],
  gate: gate.perScorer(),
})
